// Client-side search over the data generated by the SearchData pipeline (docs/src/Search/SearchData.cs).
// Usable in the browser (window.DocsSearch, requires MiniSearch) and in Node (module.exports) for testing.
(function (root, factory) {
    if (typeof module === "object" && module.exports) {
        module.exports = factory(require("minisearch"));
    } else {
        root.DocsSearch = factory(root.MiniSearch);
    }
})(this, function (MiniSearch) {
    "use strict";

    // Common words which are ignored if the query contains other words
    const STOP_WORDS = new Set([
        "a", "an", "and", "are", "as", "at", "be", "by", "can", "do", "does", "for", "from", "how", "i", "in", "is",
        "it", "of", "on", "or", "should", "that", "the", "this", "to", "we", "what", "when", "where", "which", "with",
    ]);

    const SEPARATOR = /[^\p{L}\p{N}]+/u;
    const EDGE_PUNCTUATION = /^[^\p{L}\p{N}]+|[^\p{L}\p{N}]+$/gu;
    const CAMEL_CASE_BOUNDARY = /(?<=\p{Ll})(?=\p{Lu})|(?<=\p{Lu})(?=\p{Lu}\p{Ll})|(?<=\p{L})(?=\p{N})|(?<=\p{N})(?=\p{L})/u;

    function trimPunctuation(word) {
        return word.replace(EDGE_PUNCTUATION, "");
    }

    function normalize(term) {
        return term.normalize("NFD").replace(/\p{M}/gu, "").toLowerCase();
    }

    // Splits text into terms. Compound words such as "TimerJobBase.Execute", "x-api-key" or "MSV1_0" are
    // indexed as a whole and as their parts, camel case words such as "TimerJobBase" also as "timer", "job" and "base".
    function tokenize(text) {
        const tokens = new Set();
        for (const word of text.split(/\s+/)) {
            const compound = trimPunctuation(word);
            if (!compound) {
                continue;
            }
            tokens.add(compound);
            for (const part of compound.split(SEPARATOR)) {
                if (part !== compound) {
                    tokens.add(part);
                }
                for (const subPart of part.split(CAMEL_CASE_BOUNDARY)) {
                    if (subPart.length > 1 && subPart !== part) {
                        tokens.add(subPart);
                    }
                }
            }
        }
        return [...tokens];
    }

    // Splits a query into terms. Compound words match either the compound itself or all of its parts.
    // The last word is matched as prefix, as the user might still be typing it.
    function parseQuery(query) {
        const words = query.split(/\s+/).map(trimPunctuation).filter(Boolean);
        const meaningful = words.filter(word => !STOP_WORDS.has(word.toLowerCase()));
        return (meaningful.length > 0 ? meaningful : words).map((word, i, all) => {
            const parts = word.split(SEPARATOR).filter(Boolean);
            const queries = parts.length > 1 ? [word, { combineWith: "AND", queries: parts }] : [word];
            return { combineWith: "OR", queries, prefix: i === all.length - 1 && (term => term.length > 1) };
        });
    }

    const SEARCH_OPTIONS = {
        boost: { title: 5, headings: 2, text: 1 },
        weights: { prefix: 0.2, fuzzy: 0.3 },
        boostDocument: (id, term, storedFields) => storedFields.api ? 0.3 : 1,
        // Terms are already split by parseQuery
        tokenize: term => [term],
    };

    // Pages titled like the query or containing it as exact phrase are ranked higher
    const PHRASE_BOOST = { exactTitle: 4, title: 3, text: 2 };

    const lowerTexts = new WeakMap();

    function lowerText(entry) {
        if (!lowerTexts.has(entry)) {
            lowerTexts.set(entry, normalize(entry.text));
        }
        return lowerTexts.get(entry);
    }

    // Tries strict matching first and only relaxes it if nothing is found
    const STRATEGIES = [
        { combineWith: "AND" },
        { combineWith: "AND", fuzzy: term => term.length > 4 ? 0.2 : false },
        { combineWith: "OR", partial: true },
    ];

    function createIndex(entries) {
        const index = new MiniSearch({
            idField: "id",
            fields: ["title", "headings", "text"],
            storeFields: ["api"],
            tokenize,
            processTerm: normalize,
            searchOptions: SEARCH_OPTIONS,
        });
        index.addAll(entries.map((entry, id) => ({
            id,
            title: entry.title,
            headings: entry.sections.map(section => section.title).join(" "),
            text: entry.text,
            api: entry.api,
        })));
        return index;
    }

    // Finds the position in the text where the phrase or most of the matched terms occur close together
    function findBestMatch(text, phrase, terms) {
        if (phrase && text.includes(phrase)) {
            return text.indexOf(phrase);
        }
        const windowSize = 200;
        let best = { position: -1, count: 0 };
        for (const term of terms) {
            let position = text.indexOf(term);
            for (let i = 0; position >= 0 && i < 20; i++) {
                const start = Math.max(0, position - windowSize / 2);
                const nearby = text.slice(start, start + windowSize);
                const count = terms.filter(t => nearby.includes(t)).length;
                if (count > best.count) {
                    best = { position, count };
                }
                position = text.indexOf(term, position + term.length);
            }
        }
        return best.position;
    }

    function escapeHtml(text) {
        return text.replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "\"": "&quot;", "'": "&#39;" })[c]);
    }

    function escapeRegExp(text) {
        return text.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    }

    function highlight(text, terms) {
        if (terms.length === 0) {
            return escapeHtml(text);
        }
        const pattern = new RegExp(terms.slice().sort((a, b) => b.length - a.length).map(escapeRegExp).join("|"), "gi");
        let html = "";
        let last = 0;
        for (const match of text.matchAll(pattern)) {
            html += escapeHtml(text.slice(last, match.index)) + "<mark>" + escapeHtml(match[0]) + "</mark>";
            last = match.index + match[0].length;
        }
        return html + escapeHtml(text.slice(last));
    }

    // Text fragment (https://developer.mozilla.org/en-US/docs/Web/URI/Fragment/Text_fragments) of the whole words
    // at the given position, so the browser scrolls to and highlights the match
    function textFragment(text, position, length) {
        let start = position;
        let end = position + length;
        while (start > 0 && !/\s/.test(text[start - 1])) {
            start--;
        }
        while (end < text.length && !/\s/.test(text[end])) {
            end++;
        }
        const word = trimPunctuation(text.slice(start, end));
        return word ? ":~:text=" + encodeURIComponent(word).replace(/-/g, "%2D") : "";
    }

    function createResult(entry, searchResult, normalizedQuery, phrase) {
        // Single characters are only matched as part of compound words and would be highlighted everywhere
        const terms = Object.keys(searchResult.match).filter(term => term.length > 1);
        const position = findBestMatch(lowerText(entry), phrase, terms);

        let snippet = entry.text.slice(0, 200);
        let section = null;
        let fragment = "";
        if (position >= 0) {
            const start = Math.max(0, entry.text.lastIndexOf(" ", Math.max(0, position - 80)) + 1);
            const end = entry.text.indexOf(" ", Math.min(entry.text.length, start + 220));
            snippet = (start > 0 ? "… " : "") + entry.text.slice(start, end < 0 ? undefined : end) + (end < 0 ? "" : " …");
            section = entry.sections.filter(s => s.offset <= position).pop() || null;
            fragment = textFragment(entry.text, position, phrase && lowerText(entry).startsWith(phrase, position) ? phrase.length : 0);
        }

        let score = searchResult.score;
        if (normalize(entry.title) === normalizedQuery) {
            score *= PHRASE_BOOST.exactTitle;
        } else if (phrase && normalize(entry.title).includes(phrase)) {
            score *= PHRASE_BOOST.title;
        } else if (phrase && lowerText(entry).includes(phrase)) {
            score *= PHRASE_BOOST.text;
        }

        const anchor = (section ? section.id : "") + fragment;
        return {
            link: entry.link + (anchor ? "#" + anchor : ""),
            titleHtml: highlight(entry.title, terms),
            sectionHtml: section ? highlight(section.title, terms) : null,
            snippetHtml: highlight(snippet, terms),
            api: entry.api,
            score,
        };
    }

    function search(index, entries, query) {
        const queries = parseQuery(query);
        if (queries.length === 0) {
            return { results: [], partial: false };
        }
        const words = query.split(/\s+/).map(trimPunctuation).filter(Boolean);
        const normalizedQuery = normalize(words.join(" "));
        const phrase = words.length > 1 ? normalizedQuery : null;
        for (const strategy of STRATEGIES) {
            const found = index.search({ combineWith: strategy.combineWith, queries }, strategy);
            if (found.length > 0) {
                return {
                    results: found
                        .map(searchResult => createResult(entries[searchResult.id], searchResult, normalizedQuery, phrase))
                        .sort((a, b) => b.score - a.score),
                    partial: !!strategy.partial,
                };
            }
        }
        return { results: [], partial: false };
    }

    async function load(url) {
        const response = await fetch(url);
        if (!response.ok) {
            throw new Error(`Loading search data failed: ${response.status} ${response.statusText}`);
        }
        const entries = await new Response(response.body.pipeThrough(new DecompressionStream("gzip"))).json();
        const index = createIndex(entries);
        return { search: query => search(index, entries, query) };
    }

    return { load, createIndex, search, tokenize, parseQuery };
});
